#include <Wire.h>
#include <HijelHID_BLEMouse.h>

// ESP32-C3 SuperMini + GY-521 (MPU6050)
// Existing wiring: SDA -> GPIO 0, SCL -> GPIO 1
HijelBLEMouse mouse("Air Mouse C3", "DIY");

static const uint8_t MPU_ADDR = 0x68;
static const int SDA_PIN = 0;
static const int SCL_PIN = 1;

// Adjust these after testing cursor sensitivity.
static const float SENSITIVITY = 0.035f;
static const int DEAD_ZONE = 2;

float gyroXBias = 0;
float gyroYBias = 0;

bool writeMPU(uint8_t reg, uint8_t value) {
  Wire.beginTransmission(MPU_ADDR);
  Wire.write(reg);
  Wire.write(value);
  return Wire.endTransmission() == 0;
}

bool readMPU(uint8_t reg, uint8_t *data, uint8_t length) {
  Wire.beginTransmission(MPU_ADDR);
  Wire.write(reg);
  if (Wire.endTransmission(false) != 0) return false;

  uint8_t received = Wire.requestFrom(MPU_ADDR, length, (uint8_t)true);
  if (received != length) return false;

  for (uint8_t i = 0; i < length; i++) data[i] = Wire.read();
  return true;
}

int16_t readInt16(uint8_t highReg) {
  uint8_t b[2];
  if (!readMPU(highReg, b, 2)) return 0;
  return (int16_t)((b[0] << 8) | b[1]);
}

void calibrateGyro() {
  long sumX = 0;
  long sumY = 0;
  const int samples = 400;

  // Keep the sensor completely still during this short calibration.
  for (int i = 0; i < samples; i++) {
    sumX += readInt16(0x43); // Gyro X
    sumY += readInt16(0x45); // Gyro Y
    delay(3);
  }

  gyroXBias = (float)sumX / samples;
  gyroYBias = (float)sumY / samples;
}

void setup() {
  Serial.begin(115200);

  Wire.begin(SDA_PIN, SCL_PIN);
  Wire.setClock(100000);

  // Wake MPU6050; select gyro range +/-250 degrees/sec.
  writeMPU(0x6B, 0x00); // PWR_MGMT_1
  delay(100);
  writeMPU(0x1B, 0x00); // GYRO_CONFIG

  // Verify that the sensor responds before starting BLE.
  uint8_t whoAmI = 0;
  if (!readMPU(0x75, &whoAmI, 1) || (whoAmI != 0x68 && whoAmI != 0x69)) {
    Serial.println("MPU6050 not detected. Check VCC, GND, SDA GPIO0, SCL GPIO1.");
    while (true) delay(1000);
  }

  Serial.println("Keep the Air Mouse still: calibrating gyro...");
  calibrateGyro();
  Serial.println("Calibration done. Pair 'Air Mouse C3' in phone Bluetooth settings.");

  mouse.begin();
}

void loop() {
  if (!mouse.isPaired()) {
    delay(20);
    return;
  }

  // Gyro raw scale at +/-250 dps is 131 LSB per degree/sec.
  int16_t rawX = readInt16(0x43);
  int16_t rawY = readInt16(0x45);

  float gx = ((float)rawY - gyroYBias) / 131.0f;
  float gy = ((float)rawX - gyroXBias) / 131.0f;

  int dx = (int)(gx * SENSITIVITY);
  int dy = (int)(gy * SENSITIVITY);

  if (abs(dx) < DEAD_ZONE) dx = 0;
  if (abs(dy) < DEAD_ZONE) dy = 0;

  // Flip signs here later if cursor direction feels reversed.
  if (dx != 0 || dy != 0) {
    mouse.move(dx, dy);
  }

  delay(8);
}
